css='''*{box-sizing:border-box}html{scroll-behavior:smooth}body{margin:0;background:#F6F7F2;color:#17382D;font:15px/1.5 -apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif}a{color:#245B42;text-decoration-thickness:1px;text-underline-offset:3px}a:hover{color:#17382D}a:focus-visible,button:focus-visible,input:focus-visible,select:focus-visible{outline:3px solid #28633F;outline-offset:4px}header{background:#FEFEFA;border-bottom:1px solid #D7DFD1;padding:36px max(24px,calc((100% - 1500px)/2)) 28px}h1{font-size:32px;letter-spacing:-.025em;line-height:1.15;margin:8px 0 14px}header>p{max-width:940px;margin:0 0 16px}.eyebrow{font-size:12px;letter-spacing:.1em;text-transform:uppercase;font-weight:700;color:#4C6051}.status{display:inline-block;background:#EAF0E4;border:1px solid #CBD9BF;border-radius:5px;padding:5px 9px;font-size:13px;font-weight:600}.workspace-link{margin-left:14px}.shell{display:grid;grid-template-columns:240px minmax(0,1fr);max-width:1548px;margin:auto;gap:28px;padding:28px 24px 70px}.sidebar{align-self:start;position:sticky;top:18px}.sidebar h2{font-size:13px;margin:0 0 10px}.sidebar a{display:block;padding:7px 9px;border-radius:5px;text-decoration:none;font-size:13px}.sidebar a:hover{background:#EAF0E4}.filters{display:flex;gap:6px;flex-wrap:wrap;margin:0 0 18px}button{font:inherit;color:inherit;background:#FEFEFA;border:1px solid #C8D5BF;border-radius:5px;padding:7px 10px;cursor:pointer}button[aria-pressed=true]{background:#245B42;color:#FEFEFA;border-color:#245B42}.limit{background:#FEFEFA;border:1px solid #D7DFD1;padding:18px 20px;border-radius:8px;margin-bottom:24px}.limit h2{font-size:16px;margin:0 0 8px}.limit p{margin:6px 0;font-size:13px;color:#4C6051}.review-card{background:#FEFEFA;border:1px solid #D7DFD1;border-radius:10px;margin:0 0 28px;padding:20px;scroll-margin-top:18px}.card-heading{display:flex;justify-content:space-between;gap:20px;align-items:start}.card-heading h2{font-size:21px;line-height:1.2;margin:5px 0 10px}.badge{font-size:11px;font-weight:700;letter-spacing:.04em;text-transform:uppercase;margin:0;color:#4C6051}.badge.proposal{color:#8B5533}.size{font-variant-numeric:tabular-nums;font-size:13px;color:#4C6051;white-space:nowrap;margin:3px 0}.note{font-size:13px;margin:0 0 12px;color:#4C6051;max-width:860px}.links{display:flex;gap:16px;flex-wrap:wrap;font-size:12px;margin:0 0 18px}.pair{display:grid;grid-template-columns:1fr 1fr;gap:16px}figure{margin:0;border:1px solid #D7DFD1;background:#F2F4EE;border-radius:6px;overflow:hidden;min-width:0}figcaption{background:#FEFEFA;padding:11px 12px;display:grid;gap:2px;border-bottom:1px solid #D7DFD1;font-size:13px}.load-status{font-size:11px;color:#67745E}.zoom-image{display:flex;align-items:start;justify-content:center;min-height:130px;max-height:620px;overflow:auto;cursor:zoom-in}.zoom-image img{display:block;max-width:100%;width:auto;height:auto;object-fit:contain;align-self:start}.zoom-image img[data-missing=true]{min-height:130px;font-size:13px;padding:15px}.file-link{font-size:11px;padding:8px 12px;border-top:1px solid #D7DFD1;background:#FEFEFA}dialog{border:0;border-radius:8px;padding:0;width:calc(100vw - 40px);height:calc(100vh - 40px);max-width:none;max-height:none;background:#F6F7F2;color:#17382D}dialog::backdrop{background:#17382DA8}.zoom-bar{display:flex;align-items:center;gap:14px;padding:10px 14px;border-bottom:1px solid #C8D5BF;background:#FEFEFA;flex-wrap:wrap}.zoom-bar strong{margin-right:auto;font-size:14px}.zoom-bar label{font-size:12px;display:flex;align-items:center;gap:8px}.zoom-bar input{width:140px}.zoom-content{overflow:auto;max-height:calc(100% - 65px);padding:20px;display:block}.zoom-content img{display:block;max-width:100%;height:auto;margin:auto}.footer-note{font-size:12px;color:#4C6051;margin:24px 0}body:has(dialog[open]){overflow:hidden}[hidden]{display:none!important}@media(max-width:900px){.shell{grid-template-columns:1fr}.sidebar{position:static}.sidebar nav{display:flex;flex-wrap:wrap;gap:4px}.sidebar nav a{border:1px solid #D7DFD1}.pair{grid-template-columns:1fr}.card-heading{flex-wrap:wrap;gap:0}.review-card{padding:14px}}@media(prefers-reduced-motion:reduce){html{scroll-behavior:auto}}'''
script='''const dialog=document.querySelector('dialog'),zoomImage=document.querySelector('#zoom-target'),zoomSlider=document.querySelector('#zoom-level'),zoomValue=document.querySelector('#zoom-value');let logicalWidth=0;document.querySelectorAll('.zoom-image img').forEach(image=>{const state=image.closest('figure').querySelector('.load-status');image.addEventListener('load',()=>{state.textContent='PNG file loaded · visual acceptance is separate';image.dataset.missing='false'});image.addEventListener('error',()=>{state.textContent='Export not yet available here · refresh after it is saved';image.dataset.missing='true'});if(image.complete&&image.naturalWidth)state.textContent='PNG file loaded · visual acceptance is separate'});document.querySelectorAll('.zoom-image').forEach(link=>link.addEventListener('click',event=>{const image=link.querySelector('img');if(!image.naturalWidth)return;event.preventDefault();zoomImage.src=link.href;zoomImage.alt=link.dataset.title;document.querySelector('#zoom-title').textContent=link.dataset.title;logicalWidth=image.naturalWidth/2;zoomSlider.value=100;zoomValue.textContent='Fit';zoomImage.style.width='auto';zoomImage.style.maxWidth='100%';dialog.showModal()}));document.querySelector('#close-zoom').addEventListener('click',()=>dialog.close());document.querySelector('#fit-zoom').addEventListener('click',()=>{zoomImage.style.width='auto';zoomImage.style.maxWidth='100%';zoomValue.textContent='Fit'});zoomSlider.addEventListener('input',()=>{zoomImage.style.maxWidth='none';zoomImage.style.width=logicalWidth*Number(zoomSlider.value)/100+'px';zoomValue.textContent=zoomSlider.value+'%'});document.querySelectorAll('[data-filter]').forEach(button=>button.addEventListener('click',()=>{const filter=button.dataset.filter;document.querySelectorAll('[data-filter]').forEach(x=>x.setAttribute('aria-pressed',String(x===button)));document.querySelectorAll('.review-card,.sidebar nav a').forEach(x=>x.hidden=filter!=='all'&&x.dataset.kind!==filter)}));'''
page=f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta http-equiv="Content-Security-Policy" content="default-src 'none'; img-src 'self' file:; style-src 'unsafe-inline'; script-src 'unsafe-inline'; base-uri 'none'; form-action 'none'"><title>Phase 01 · Penpot design review</title><style>{css}</style></head><body><header><div class="eyebrow">Dakhl_Restaurant · Phase 01</div><h1>Designs &amp; structural wireframes</h1><p>Compare the native Penpot export candidates with the supplied references. Reference reproductions and proposed usability adaptations are separated below; all design approval remains pending.</p><span class="status">Review candidate · explicit approval required</span><a class="workspace-link" target="_blank" rel="noopener" href="https://design.penpot.app/#/workspace?team-id=bfddaaba-4180-81d4-8008-db9f13093baa&amp;file-id=122350ae-89ad-8027-8008-dba0bd5cf454&amp;page-id=122350ae-89ad-8027-8008-dba0bd5cf455">Open canonical Penpot page ↗</a></header><div class="shell"><aside class="sidebar"><h2>Review set</h2><div class="filters" aria-label="Filter design candidates"><button data-filter="all" aria-pressed="true">All</button><button data-filter="reference" aria-pressed="false">References</button><button data-filter="proposal" aria-pressed="false">Proposals</button></div><nav aria-label="Review boards">{''.join(nav)}</nav><p class="footer-note">Click an export to zoom. Use Escape to close the viewer. 100% zoom uses the board’s logical size; PNG exports are stored at 2×.</p></aside><main><section class="limit"><h2>What this review establishes</h2><p>This gallery loads local PNG exports. A loaded file is not a visual pass, pixel-identity claim, accessibility certification or approval. Missing exports remain visibly pending.</p><p>Static artwork cannot establish keyboard focus, screen-reader behavior, native safe areas, physical keyboard/IME behavior, text scaling, persistence or recovery. These remain implementation/runtime checks.</p><p>Source-capture comparison: five supplied views match their frozen PNGs after documented synthetic presentation alignment of the invoice footer to 137,500 and narrow catalog requested counts to zero. Narrow sales retains 368 changed pixels inside photos or within one logical pixel of photo edges, with none outside those regions. Earlier small pixel counts had concealed real amount/quantity mismatches; those were corrected explicitly. These figures describe source captures, not the native exports shown here.</p><p>Reference lettering can be outlined vectors; source strings are retained separately. Font hinting, image sampling and other native-export differences require the evidence record. No application implementation, merge, publication or release approval is implied.</p><div class="links"><a href="../source-artwork/source-verification.json" target="_blank" rel="noopener">Source evidence ↗</a><a href="../reference-data/manifest.json" target="_blank" rel="noopener">Capture evidence ↗</a></div></section>{''.join(cards)}<p class="footer-note">Local review artifact · 29 October 2026. Engine Design: N/A for this app-owned presentation scope; reviewed engine revision remains unchanged.</p></main></div><dialog aria-labelledby="zoom-title"><div class="zoom-bar"><strong id="zoom-title">Export preview</strong><label>Zoom <input id="zoom-level" type="range" min="25" max="200" step="25" value="100"><span id="zoom-value">Fit</span></label><button id="fit-zoom">Fit</button><button id="close-zoom">Close · Esc</button></div><div class="zoom-content"><img id="zoom-target" alt=""></div></dialog><script>{script}</script></body></html>'''
(out/'index.html').write_text(page)
checks=[]
for screen,*_ in entries:
 for mode in ['design','wireframe']:
  p=native/f'{screen}-{mode}.png';entry={'screen':screen,'kind':mode,'file':str(p),'exists':p.is_file()}
  if p.is_file():
   b=p.read_bytes();entry.update({'pixels':struct.unpack('>II',b[16:24]),'sha256':hashlib.sha256(b).hexdigest()})
  checks.append(entry)
(out/'availability-at-build.json').write_text(json.dumps({'date':'2026-10-29','note':'File-existence snapshot only; native export visual verification belongs to Lead. Refresh this build after exports finish.','files':checks},indent=2)+'\n')
print('Gallery',out/'index.html');print('Cards',len(entries),'PNG slots',len(checks),'currently available',sum(x['exists'] for x in checks),'pending',sum(not x['exists'] for x in checks))
